import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { evolvePath, getLength, getPointAtLength } from "@remotion/paths";

{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type LineChartRaceProps = Record<string, any>;

// Static data based on the prompt's progression, ending at 17.5M and 16.99M
const lgbtqData = [
  10.0, 10.5, 10.8, 11.2, 11.5, 11.9, 12.4, 12.8, 13.3, 13.8, 
  14.4, 15.0, 15.7, 16.3, 16.8, 17.2, 17.5
];

const pickleballData = [
  1.0, 1.1, 1.4, 1.6, 1.4, 1.8, 2.4, 3.5, 4.5, 5.9, 
  7.7, 9.7, 12.1, 14.3, 15.8, 16.5, 16.99
];

const years = Array.from({length: 17}, (_, i) => 2010 + i);

const getSmoothPath = (points: {x: number, y: number}[]) => {
  if (points.length === 0) return '';
  let d = `M ${points[0].x} ${points[0].y}`;
  for (let i = 0; i < points.length - 1; i++) {
    const p0 = i === 0 ? points[0] : points[i - 1];
    const p1 = points[i];
    const p2 = points[i + 1];
    const p3 = i === points.length - 2 ? points[i + 1] : points[i + 2];

    const cp1x = p1.x + (p2.x - p0.x) / 6;
    const cp1y = p1.y + (p2.y - p0.y) / 6;
    const cp2x = p2.x - (p3.x - p1.x) / 6;
    const cp2y = p2.y - (p3.y - p1.y) / 6;

    d += ` C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${p2.x} ${p2.y}`;
  }
  return d;
};

const LineChartRace: React.FC<LineChartRaceProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 12,
  title = "Pickleball vs. LGBTQ Community",
  lgbtqColor = "#FF00FF",
  pickleballColor = "#D0F04A",
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const MARGIN_LEFT = 150;
  const MARGIN_RIGHT = 350; 
  const MARGIN_TOP = 200;
  const MARGIN_BOTTOM = 200;

  const chartWidth = width - MARGIN_LEFT - MARGIN_RIGHT;
  const chartHeight = height - MARGIN_TOP - MARGIN_BOTTOM;

  const maxVal = 20;
  const yLabels = [0, 5, 10, 15, 20];
  const xLabelsIndices = [0, 5, 10, 16];

  const mapX = (index: number) => MARGIN_LEFT + (index / (years.length - 1)) * chartWidth;
  const mapY = (val: number) => (height - MARGIN_BOTTOM) - (val / maxVal) * chartHeight;

  const { lgbtqPathStr, pickleballPathStr, lgbtqLen, pbLen } = useMemo(() => {
    const lPoints = lgbtqData.map((val, i) => ({ x: mapX(i), y: mapY(val) }));
    const pPoints = pickleballData.map((val, i) => ({ x: mapX(i), y: mapY(val) }));
    const lPath = getSmoothPath(lPoints);
    const pPath = getSmoothPath(pPoints);
    return {
      lgbtqPathStr: lPath,
      pickleballPathStr: pPath,
      lgbtqLen: getLength(lPath),
      pbLen: getLength(pPath)
    };
  }, [width, height]);

  const durationInFrames = durationInSeconds * fps;
  const holdFrames = 60; // 2 seconds hold at the end
  const animFrames = durationInFrames - holdFrames;

  const lineProgress = interpolate(frame, [0, animFrames], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp'
  });

  const isFinished = lineProgress === 1;
  const pulseFrame = isFinished ? frame - animFrames : 0;
  
  const popSpring = spring({ frame: pulseFrame, fps, config: { damping: 10, stiffness: 100 } });
  const labelScale = isFinished ? interpolate(popSpring, [0, 1], [1.3, 1]) : 1;

  const lgbtqEvolution = evolvePath(lineProgress, lgbtqPathStr);
  const pbEvolution = evolvePath(lineProgress, pickleballPathStr);

  const safeProgress = Math.max(0.0001, lineProgress);
  const lgbtqPoint = getPointAtLength(lgbtqPathStr, lgbtqLen * safeProgress);
  const pbPoint = getPointAtLength(pickleballPathStr, pbLen * safeProgress);

  const valFromY = (y: number) => Math.max(0, ((height - MARGIN_BOTTOM) - y) / chartHeight * maxVal);

  const currentLgbtqVal = valFromY(lgbtqPoint.y);
  const currentPbVal = valFromY(pbPoint.y);
  const currentYear = years[0] + lineProgress * (years[years.length - 1] - years[0]);

  const fadeIn = interpolate(frame, [0, 20], [0, 1], { extrapolateRight: 'clamp' });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", opacity: fadeIn }}>
      
      {/* Title */}
      <div style={{
        position: 'absolute',
        top: 80,
        left: 0,
        width: '100%',
        textAlign: 'center',
        color: 'white',
        fontSize: 56,
        fontWeight: 'bold',
        letterSpacing: '-1px'
      }}>
        {title}
      </div>

      {/* SVG Chart Layer */}
      <svg width={width} height={height} style={{ position: 'absolute', top: 0, left: 0, overflow: 'visible' }}>
        
        {/* Horizontal Grid Lines */}
        {yLabels.map(val => (
          <line 
            key={`grid-${val}`}
            x1={MARGIN_LEFT} 
            y1={mapY(val)} 
            x2={width - MARGIN_RIGHT + 50} 
            y2={mapY(val)} 
            stroke="rgba(255,255,255,0.15)" 
            strokeWidth={2} 
          />
        ))}

        {/* Y Axis */}
        <line x1={MARGIN_LEFT} y1={MARGIN_TOP - 20} x2={MARGIN_LEFT} y2={height - MARGIN_BOTTOM} stroke="white" strokeWidth={2} />
        
        {/* X Axis */}
        <line x1={MARGIN_LEFT} y1={height - MARGIN_BOTTOM} x2={width - MARGIN_RIGHT + 50} y2={height - MARGIN_BOTTOM} stroke="white" strokeWidth={2} />

        {/* X Axis Ticks */}
        {xLabelsIndices.map(idx => (
          <line
            key={`tick-${idx}`}
            x1={mapX(idx)}
            y1={height - MARGIN_BOTTOM}
            x2={mapX(idx)}
            y2={height - MARGIN_BOTTOM + 12}
            stroke="white"
            strokeWidth={2}
          />
        ))}

        {/* LGBTQ Path */}
        <path
          d={lgbtqPathStr}
          fill="none"
          stroke={lgbtqColor}
          strokeWidth={8}
          strokeLinecap="round"
          strokeDasharray={lgbtqEvolution.strokeDasharray.toString()}
          strokeDashoffset={lgbtqEvolution.strokeDashoffset.toString()}
          style={{ filter: `drop-shadow(0 0 10px ${lgbtqColor})`, transition: 'none' }}
        />

        {/* Pickleball Path */}
        <path
          d={pickleballPathStr}
          fill="none"
          stroke={pickleballColor}
          strokeWidth={8}
          strokeLinecap="round"
          strokeDasharray={pbEvolution.strokeDasharray.toString()}
          strokeDashoffset={pbEvolution.strokeDashoffset.toString()}
          style={{ filter: `drop-shadow(0 0 10px ${pickleballColor})`, transition: 'none' }}
        />
      </svg>

      {/* Y Axis Labels */}
      {yLabels.map(val => (
        <div key={`y-label-${val}`} style={{
          position: 'absolute',
          left: MARGIN_LEFT - 100,
          top: mapY(val) - 18,
          color: 'rgba(255,255,255,0.9)',
          fontSize: 28,
          textAlign: 'right',
          width: 80
        }}>
          {val}M
        </div>
      ))}

      {/* X Axis Labels */}
      {xLabelsIndices.map(idx => {
        const year = years[idx];
        return (
          <div key={`x-label-${year}`} style={{
            position: 'absolute',
            left: mapX(idx) - 40,
            top: height - MARGIN_BOTTOM + 24,
            color: 'rgba(255,255,255,0.9)',
            fontSize: 28,
            textAlign: 'center',
            width: 80
          }}>
            {year}
          </div>
        )
      })}

      {/* LGBTQ Leading Edge Label */}
      <div style={{
        position: 'absolute',
        left: lgbtqPoint.x - 24, 
        top: lgbtqPoint.y - 24, 
        display: 'flex',
        alignItems: 'center',
        gap: 16,
        transform: `scale(${labelScale})`,
        transformOrigin: '24px 24px',
        transition: 'none',
        width: 400,
        zIndex: 10
      }}>
        <div style={{
          width: 48, height: 48, borderRadius: '50%', overflow: 'hidden',
          display: 'flex', flexDirection: 'column', border: '3px solid white',
          boxShadow: `0 0 15px ${lgbtqColor}`,
          flexShrink: 0,
          backgroundColor: '#000'
        }}>
          <div style={{flex: 1, backgroundColor: '#FF0018'}}></div>
          <div style={{flex: 1, backgroundColor: '#FFA52C'}}></div>
          <div style={{flex: 1, backgroundColor: '#FFFF41'}}></div>
          <div style={{flex: 1, backgroundColor: '#008018'}}></div>
          <div style={{flex: 1, backgroundColor: '#0000F9'}}></div>
          <div style={{flex: 1, backgroundColor: '#86007D'}}></div>
        </div>
        <div style={{ 
          color: lgbtqColor, 
          fontSize: 36, 
          fontWeight: 'bold', 
          textShadow: `0 0 12px ${lgbtqColor}80`,
          whiteSpace: 'nowrap' 
        }}>
          LGBTQ {currentLgbtqVal.toFixed(2)}M
        </div>
      </div>

      {/* Pickleball Leading Edge Label */}
      <div style={{
        position: 'absolute',
        left: pbPoint.x - 24, 
        top: pbPoint.y - 24, 
        display: 'flex',
        alignItems: 'center',
        gap: 16,
        transform: `scale(${labelScale})`,
        transformOrigin: '24px 24px',
        transition: 'none',
        width: 400,
        zIndex: 10
      }}>
        <div style={{
          width: 48, height: 48, borderRadius: '50%', backgroundColor: pickleballColor,
          border: '3px solid white', position: 'relative',
          boxShadow: `0 0 15px ${pickleballColor}`,
          flexShrink: 0
        }}>
          <div style={{position: 'absolute', width: '16%', height: '16%', borderRadius: '50%', backgroundColor: '#8DA82B', top: '25%', left: '25%'}}></div>
          <div style={{position: 'absolute', width: '12%', height: '12%', borderRadius: '50%', backgroundColor: '#8DA82B', top: '20%', right: '25%'}}></div>
          <div style={{position: 'absolute', width: '14%', height: '14%', borderRadius: '50%', backgroundColor: '#8DA82B', bottom: '30%', left: '37%'}}></div>
          <div style={{position: 'absolute', width: '12%', height: '12%', borderRadius: '50%', backgroundColor: '#8DA82B', top: '45%', left: '58%'}}></div>
        </div>
        <div style={{ 
          color: pickleballColor, 
          fontSize: 36, 
          fontWeight: 'bold', 
          textShadow: `0 0 12px ${pickleballColor}80`,
          whiteSpace: 'nowrap' 
        }}>
          Pickleball {currentPbVal.toFixed(2)}M
        </div>
      </div>

      {/* Large Year Counter */}
      <div style={{
        position: 'absolute',
        left: 0,
        top: height - 120,
        width: '100%',
        textAlign: 'center',
        color: 'white',
        fontSize: 100,
        fontWeight: 'bold',
        letterSpacing: '-2px',
        lineHeight: 1
      }}>
        {Math.floor(currentYear)}
      </div>

    </AbsoluteFill>
  );
};

export default LineChartRace;